import Foundation

struct WeatherSnapshot: Codable {
    let location: String
    let temperatureCelsius: Double
    let condition: String
}

func decodeWeather(_ data: Data) throws -> WeatherSnapshot {
    try JSONDecoder().decode(WeatherSnapshot.self, from: data)
}

let fixture = #"{"location":"Ahmedabad","temperatureCelsius":31,"condition":"Clear"}"#.data(using: .utf8)!
let weather = try decodeWeather(fixture)
print("\(weather.location): \(weather.temperatureCelsius) °C, \(weather.condition)")
